const v = validateMetadata(metadata, ctx.concept);
if (!v.ok) throw new Error('Metadata failed validation:\n- ' + v.errors.join('\n- '));
const { body, ...rest } = ctx;
rest.usage = { ...rest.usage, metadata: api.usage };
return [{ json: { ...rest, metadata, metadata_warnings: v.warnings } }];

// Builds the Slack review text. Slack section blocks cap at 3000 chars, so this stays compact.
const pkg = $input.first().json;
const c = pkg.concept, m = pkg.metadata, cfg = pkg.config;
const mmss = (s) => { const h = Math.floor(s / 3600), mi = Math.floor((s % 3600) / 60), se = s % 60; return (h ? h + ':' : '') + (h ? String(mi).padStart(2, '0') : mi) + ':' + String(se).padStart(2, '0'); };
let t = 0;
const scenes = c.scenes.map((s) => { const line = mmss(t) + ' ' + s.name + ' (' + Math.round(s.duration_seconds / 60) + ' min)'; t += s.duration_seconds; return line; });
const warnings = [...(pkg.concept_warnings || []), ...(pkg.metadata_warnings || []), ...(m.review_notes || [])];
const cut = (s, n) => (s && s.length > n ? s.slice(0, n - 1) + '\u2026' : s || '');
const lines = [
  '*Concept for review* \u2014 run `' + pkg.run_id + '` \u00b7 render mode: *' + cfg.render_mode + '*',
  '*Title:* ' + m.title,
  '*Format:* ' + c.format_family + ' \u00b7 ' + c.duration_minutes + ' min \u00b7 ' + c.scenes.length + ' scenes \u00b7 spoken intro: ' + (c.spoken_intro.enabled ? 'yes' : 'no'),
  '*Theme:* ' + cut(c.theme, 300),
  '*Why it differs from recent uploads:* ' + cut(c.variation_rationale, 400),
  '*Scenes:*\n' + scenes.join('\n'),
  '*Audio:* ' + cut(c.audio_brief.mood + ' \u00b7 ' + c.audio_brief.tonal_centre + ' \u00b7 ' + c.audio_brief.instrumentation.join(', '), 300),
  '*Tags:* ' + cut(m.tags.join(', '), 300),
  '*AI disclosure:* ' + (m.ai_disclosure.required ? 'REQUIRED' : 'not required') + ' \u2014 ' + cut(m.ai_disclosure.reason, 200),
  c.assumptions && c.assumptions.length ? '*Assumptions made:*\n\u2022 ' + c.assumptions.map((a) => cut(a, 160)).join('\n\u2022 ') : '',
  warnings.length ? '*Check before approving:*\n\u2022 ' + warnings.map((w) => cut(w, 160)).join('\n\u2022 ') : '',
  cfg.render_mode === 'creatomate' ? '_Approve = render on Creatomate, then upload to YouTube as PRIVATE._' : '_Approve = record the concept and post the render payload here. Nothing renders or uploads in stub mode._',
].filter(Boolean);
let review_message = lines.join('\n\n');
if (review_message.length > 2900) review_message = review_message.slice(0, 2890) + '\n\u2026';
return [{ json: { ...pkg, review_message } }];

function appendHistory(entry) {
  const store = $getWorkflowStaticData('global');
  store.history = Array.isArray(store.history) ? store.history : [];
  store.history.push(entry);
  if (store.history.length > 60) store.history = store.history.slice(-60);
}
const pkg = $('Assemble Review Package').first().json;
const resp = $input.first().json;
const status = resp.data && resp.data.approved === false ? 'rejected' : 'timed_out';
appendHistory({ date: pkg.today, run_id: pkg.run_id, status, format_family: pkg.concept.format_family, theme: pkg.concept.theme, palette: pkg.concept.visual_style.global_palette, mood: pkg.concept.audio_brief.mood, title: pkg.metadata.title });
const notice = status === 'rejected'
  ? ':no_entry: Concept `' + pkg.run_id + '` rejected. Nothing rendered or uploaded.'
  : ':hourglass: Concept `' + pkg.run_id + '` timed out waiting for approval and was discarded. Nothing rendered or uploaded.';
return [{ json: { run_id: pkg.run_id, status, notice } }];

// The Slack node replaces the item with {data:{approved,...}}; pull the package back from the node before it.
const pkg = $('Assemble Review Package').first().json;
const approval = $input.first().json.data || {};
